def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width horizontal stripes encode a repeating sequence of rows.
    stripes = []
    for r, row in enumerate(grid):
        if all(v == row[0] and v != 0 for v in row):
            stripes.append((r, row[0]))

    for period in range(1, h + 1):
        values = {}
        for r, color in stripes:
            residue = r % period
            if residue in values and values[residue] != color:
                break
            values[residue] = color
        else:
            if len(values) == period:
                return [[values[r % period]] * w for r in range(h)]

    # Diagonal stripes encode a periodic color pattern. Infer the period and
    # whether the stripes run along c-r or c+r.
    marks = [(r, c, grid[r][c])
             for r in range(h) for c in range(w) if grid[r][c] != 0]

    for period in range(1, max(h, w) + 1):
        for sign in (1, -1):  # residue is c-r, then c+r
            values = {}
            for r, c, color in marks:
                residue = (c + sign * r) % period
                if residue in values and values[residue] != color:
                    break
                values[residue] = color
            else:
                if len(values) == period:
                    return [[values[(c + sign * r) % period]
                             for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
